"""W2-67 batch 2 probe (throwaway): build W1-26's base project, run gov check --json, print each check's
id, family, severity, status and findings. Usage: probe_base.py <tmpdir> [<plant-callable-name>]"""

import json
import sys
from pathlib import Path

WT = Path("/home/usain/gov-os-worktrees/W2-67")
sys.path.insert(0, str(WT / "tests/acceptance/W1-26"))
import w1_26_support as support  # noqa: E402

cli = support.cli_support


def summary(run):
    data = json.loads(run.stdout)
    out = {"exit": run.returncode, "ok": data.get("ok")}
    result = data.get("result") or (data.get("error") or {}).get("details") or {}
    if not data.get("ok") and data.get("error"):
        out["error"] = {k: data["error"].get(k) for k in ("code", "message")}
    checks = support.checks_of(result)
    out["checks"] = [
        {k: c.get(k) for k in ("id", "family", "severity", "status")}
        | {"findings": [{k: f.get(k) for k in ("code", "message", "path", "id", "record") if k in f}
                        for f in (c.get("findings") or [])][:6]}
        for c in checks if isinstance(c, dict)
    ]
    fams = support.families_of(result)
    out["families"] = {name: (e.get("status") if isinstance(e, dict) else e) for name, e in fams.items()}
    out["result_keys"] = sorted(result) if isinstance(result, dict) else None
    return out


def main():
    base = Path(sys.argv[1])
    project = support.Project(base / "project")
    sandbox = cli.make_sandbox(base / "sandbox")
    if len(sys.argv) > 2:
        import probe_plants
        getattr(probe_plants, sys.argv[2])(project)
    project.commit()
    run = support.run_check(project, sandbox)
    print(json.dumps(summary(run), indent=1))


if __name__ == "__main__":
    main()
